from scipy.optimize import least_squares
def run(name, f, npar, ntry=40, seed=0):
    rng=np.random.default_rng(seed)
    best=None
    for _ in range(ntry):
        p0=rng.normal(0,1,npar)
        try:
            with np.errstate(all='ignore'):
                r=least_squares(lambda p: f(p)-sigma, p0, max_nfev=2000)
            if np.all(np.isfinite(r.fun)):
                v=np.mean(r.fun**2)/np.var(sigma)
                if best is None or v<best[0]: best=(v,r.x)
        except Exception as ex:
            pass
    if best is None:
        print(name,"failed")
    else:
        print(name, best[0], np.round(best[1],4))
    return best
